/**
 * JSON validation utility for reading and validating JSON from stdin.
 */

/**
 * Validation result type returned by validateJsonFromStdin.
 */
export interface ValidationResult {
  valid: boolean;
  data?: unknown;
  error?: string;
}

/**
 * Reads JSON from stdin asynchronously and validates it.
 * Returns an object indicating whether the input is valid JSON,
 * along with the parsed data or an error message.
 */
export async function validateJsonFromStdin(): Promise<ValidationResult> {
  try {
    // Read from stdin using Bun's built-in stdin
    const input = await Bun.stdin.text();

    // Attempt to parse the JSON
    const data = JSON.parse(input);

    return {
      valid: true,
      data,
    };
  } catch (error) {
    // Extract error message from the caught error
    const errorMessage =
      error instanceof Error ? error.message : String(error);

    return {
      valid: false,
      error: errorMessage,
    };
  }
}

/**
 * Tests for the JSON validator utility.
 */

import { describe, test, expect, beforeEach, afterEach } from "bun:test";
import { validateJsonFromStdin } from "./json-validator";

describe("validateJsonFromStdin", () => {
  test("validates valid JSON object", async () => {
    const input = '{"name": "John", "age": 30}';
    const mockStdin = new TextEncoder().encode(input);

    // Mock stdin by creating a mock Bun object
    const originalStdin = Bun.stdin;
    Object.defineProperty(Bun, "stdin", {
      value: {
        text: async () => input,
      },
      configurable: true,
    });

    try {
      const result = await validateJsonFromStdin();
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ name: "John", age: 30 });
      expect(result.error).toBeUndefined();
    } finally {
      Object.defineProperty(Bun, "stdin", {
        value: originalStdin,
        configurable: true,
      });
    }
  });

  test("validates valid JSON array", async () => {
    const input = '[1, 2, 3, "four"]';
    const originalStdin = Bun.stdin;
    Object.defineProperty(Bun, "stdin", {
      value: {
        text: async () => input,
      },
      configurable: true,
    });

    try {
      const result = await validateJsonFromStdin();
      expect(result.valid).toBe(true);
      expect(result.data).toEqual([1, 2, 3, "four"]);
      expect(result.error).toBeUndefined();
    } finally {
      Object.defineProperty(Bun, "stdin", {
        value: originalStdin,
        configurable: true,
      });
    }
  });

  test("handles invalid JSON", async () => {
    const input = '{invalid json}';
    const originalStdin = Bun.stdin;
    Object.defineProperty(Bun, "stdin", {
      value: {
        text: async () => input,
      },
      configurable: true,
    });

    try {
      const result = await validateJsonFromStdin();
      expect(result.valid).toBe(false);
      expect(result.data).toBeUndefined();
      expect(result.error).toBeDefined();
    } finally {
      Object.defineProperty(Bun, "stdin", {
        value: originalStdin,
        configurable: true,
      });
    }
  });

  test("handles empty input", async () => {
    const input = "";
    const originalStdin = Bun.stdin;
    Object.defineProperty(Bun, "stdin", {
      value: {
        text: async () => input,
      },
      configurable: true,
    });

    try {
      const result = await validateJsonFromStdin();
      expect(result.valid).toBe(false);
      expect(result.data).toBeUndefined();
      expect(result.error).toBeDefined();
    } finally {
      Object.defineProperty(Bun, "stdin", {
        value: originalStdin,
        configurable: true,
      });
    }
  });

  test("handles nested JSON objects", async () => {
    const input = '{"user": {"name": "Alice", "profile": {"age": 25}}}';
    const originalStdin = Bun.stdin;
    Object.defineProperty(Bun, "stdin", {
      value: {
        text: async () => input,
      },
      configurable: true,
    });

    try {
      const result = await validateJsonFromStdin();
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({
        user: { name: "Alice", profile: { age: 25 } },
      });
      expect(result.error).toBeUndefined();
    } finally {
      Object.defineProperty(Bun, "stdin", {
        value: originalStdin,
        configurable: true,
      });
    }
  });

  test("handles whitespace in input", async () => {
    const input = '  \n  {"key": "value"}  \n  ';
    const originalStdin = Bun.stdin;
    Object.defineProperty(Bun, "stdin", {
      value: {
        text: async () => input,
      },
      configurable: true,
    });

    try {
      const result = await validateJsonFromStdin();
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ key: "value" });
      expect(result.error).toBeUndefined();
    } finally {
      Object.defineProperty(Bun, "stdin", {
        value: originalStdin,
        configurable: true,
      });
    }
  });
});

/**
 * Command-line interface for the JSON validator tool.
 * Usage: bun run src/cli.ts < input.json
 */

import { validateJsonFromStdin } from "./json-validator";

/**
 * Main CLI entry point. Reads JSON from stdin, validates it, and prints the result.
 */
async function main(): Promise<void> {
  const result = await validateJsonFromStdin();

  if (result.valid) {
    console.log("Valid JSON");
    console.log("Data:", JSON.stringify(result.data, null, 2));
  } else {
    console.error("Invalid JSON");
    console.error("Error:", result.error);
    process.exit(1);
  }
}

main().catch((error) => {
  console.error("Unexpected error:", error);
  process.exit(1);
});

