/**
 * Tests for the JSON validator utility.
 */

import { describe, test, expect } from "bun:test";
import { validateJson } from "./json-validator";

describe("validateJson", () => {
  test("validates valid JSON object", () => {
    const input = '{"name": "John", "age": 30}';
    const result = validateJson(input);

    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ name: "John", age: 30 });
    expect(result.error).toBeUndefined();
  });

  test("validates valid JSON array", () => {
    const input = '[1, 2, 3, "four"]';
    const result = validateJson(input);

    expect(result.valid).toBe(true);
    expect(result.data).toEqual([1, 2, 3, "four"]);
    expect(result.error).toBeUndefined();
  });

  test("validates JSON primitives", () => {
    expect(validateJson('"string"').valid).toBe(true);
    expect(validateJson('"string"').data).toBe("string");

    expect(validateJson("42").valid).toBe(true);
    expect(validateJson("42").data).toBe(42);

    expect(validateJson("true").valid).toBe(true);
    expect(validateJson("true").data).toBe(true);

    expect(validateJson("null").valid).toBe(true);
    expect(validateJson("null").data).toBe(null);
  });

  test("handles invalid JSON", () => {
    const input = "{invalid json}";
    const result = validateJson(input);

    expect(result.valid).toBe(false);
    expect(result.data).toBeUndefined();
    expect(result.error).toBeDefined();
  });

  test("handles empty input", () => {
    const input = "";
    const result = validateJson(input);

    expect(result.valid).toBe(false);
    expect(result.data).toBeUndefined();
    expect(result.error).toBeDefined();
  });

  test("handles nested JSON objects", () => {
    const input = '{"user": {"name": "Alice", "profile": {"age": 25}}}';
    const result = validateJson(input);

    expect(result.valid).toBe(true);
    expect(result.data).toEqual({
      user: { name: "Alice", profile: { age: 25 } },
    });
    expect(result.error).toBeUndefined();
  });

  test("handles whitespace in input", () => {
    const input = '  \n  {"key": "value"}  \n  ';
    const result = validateJson(input);

    expect(result.valid).toBe(true);
    expect(result.data).toEqual({ key: "value" });
    expect(result.error).toBeUndefined();
  });

  test("handles invalid JSON with unterminated string", () => {
    const input = '{"key": "unterminated';
    const result = validateJson(input);

    expect(result.valid).toBe(false);
    expect(result.data).toBeUndefined();
    expect(result.error).toBeDefined();
  });
});

