/**
 * Utility functions for the eval test project.
 */

/**
 * Greet someone by name.
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

/**
 * Greet someone formally by name.
 * Provides a more formal greeting suitable for professional contexts.
 */
export function greetFormal(name: string): string {
  return `Dear ${name}, it is a pleasure to make your acquaintance.`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

