import { describe, expect, test } from "bun:test";
import { greet, greetFormal, add } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("greetFormal returns formal greeting message", () => {
    expect(greetFormal("Bob")).toBe("Dear Bob, it is a pleasure to make your acquaintance.");
  });

  test("greetFormal works with different names", () => {
    expect(greetFormal("Charlie")).toBe("Dear Charlie, it is a pleasure to make your acquaintance.");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

